CREATE TYPE "DocumentClassification" AS ENUM ('INTERNAL', 'CONFIDENTIAL', 'RESTRICTED');
CREATE TYPE "ProjectStatus" AS ENUM ('PLANNING', 'ACTIVE', 'COMPLETED', 'ARCHIVED');
CREATE TYPE "TaskStatus" AS ENUM ('BACKLOG', 'TODO', 'IN_PROGRESS', 'REVIEW', 'DONE', 'CANCELLED');
CREATE TYPE "TaskPriority" AS ENUM ('LOW', 'MEDIUM', 'HIGH', 'URGENT');
CREATE TYPE "ApprovalStatus" AS ENUM ('DRAFT', 'SUBMITTED', 'IN_REVIEW', 'APPROVED', 'REJECTED', 'CANCELLED', 'CHANGES_REQUESTED');
CREATE TYPE "ApprovalActionType" AS ENUM ('APPROVE', 'REJECT', 'REQUEST_CHANGES');

CREATE TABLE "documents" ("id" UUID NOT NULL, "name" VARCHAR(255) NOT NULL, "description" VARCHAR(1000), "classification" "DocumentClassification" NOT NULL DEFAULT 'INTERNAL', "folder_path" VARCHAR(1000) NOT NULL DEFAULT '/', "mime_type" VARCHAR(150) NOT NULL, "size_bytes" BIGINT NOT NULL, "storage_key" VARCHAR(500) NOT NULL, "owner_id" UUID NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "documents_pkey" PRIMARY KEY ("id"));
CREATE TABLE "document_versions" ("id" UUID NOT NULL, "document_id" UUID NOT NULL, "version" INTEGER NOT NULL, "size_bytes" BIGINT NOT NULL, "mime_type" VARCHAR(150) NOT NULL, "storage_key" VARCHAR(500) NOT NULL, "created_by" UUID NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "document_versions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "projects" ("id" UUID NOT NULL, "name" VARCHAR(180) NOT NULL, "description" TEXT, "status" "ProjectStatus" NOT NULL DEFAULT 'PLANNING', "owner_id" UUID NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "projects_pkey" PRIMARY KEY ("id"));
CREATE TABLE "project_members" ("project_id" UUID NOT NULL, "user_id" UUID NOT NULL, CONSTRAINT "project_members_pkey" PRIMARY KEY ("project_id", "user_id"));
CREATE TABLE "tasks" ("id" UUID NOT NULL, "project_id" UUID NOT NULL, "title" VARCHAR(240) NOT NULL, "description" TEXT, "status" "TaskStatus" NOT NULL DEFAULT 'TODO', "priority" "TaskPriority" NOT NULL DEFAULT 'MEDIUM', "due_date" TIMESTAMP(3), "creator_id" UUID NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "tasks_pkey" PRIMARY KEY ("id"));
CREATE TABLE "task_assignees" ("task_id" UUID NOT NULL, "user_id" UUID NOT NULL, CONSTRAINT "task_assignees_pkey" PRIMARY KEY ("task_id", "user_id"));
CREATE TABLE "approval_requests" ("id" UUID NOT NULL, "type" VARCHAR(100) NOT NULL, "title" VARCHAR(240) NOT NULL, "payload" JSONB NOT NULL, "status" "ApprovalStatus" NOT NULL DEFAULT 'DRAFT', "requester_id" UUID NOT NULL, "reviewer_id" UUID, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "approval_requests_pkey" PRIMARY KEY ("id"));
CREATE TABLE "approval_actions" ("id" UUID NOT NULL, "request_id" UUID NOT NULL, "actor_id" UUID NOT NULL, "type" "ApprovalActionType" NOT NULL, "comment" VARCHAR(1000), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "approval_actions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "notifications" ("id" UUID NOT NULL, "user_id" UUID NOT NULL, "title" VARCHAR(180) NOT NULL, "message" VARCHAR(1000) NOT NULL, "link" VARCHAR(500), "read_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "notifications_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "documents_storage_key_key" ON "documents"("storage_key");
CREATE UNIQUE INDEX "document_versions_storage_key_key" ON "document_versions"("storage_key");
CREATE UNIQUE INDEX "document_versions_document_id_version_key" ON "document_versions"("document_id", "version");
CREATE INDEX "documents_owner_id_created_at_idx" ON "documents"("owner_id", "created_at");
CREATE INDEX "documents_folder_path_created_at_idx" ON "documents"("folder_path", "created_at");
CREATE INDEX "projects_owner_id_status_idx" ON "projects"("owner_id", "status");
CREATE INDEX "tasks_project_id_status_due_date_idx" ON "tasks"("project_id", "status", "due_date");
CREATE INDEX "approval_requests_requester_id_status_created_at_idx" ON "approval_requests"("requester_id", "status", "created_at");
CREATE INDEX "approval_actions_request_id_created_at_idx" ON "approval_actions"("request_id", "created_at");
CREATE INDEX "notifications_user_id_read_at_created_at_idx" ON "notifications"("user_id", "read_at", "created_at");

ALTER TABLE "documents" ADD CONSTRAINT "documents_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "document_versions" ADD CONSTRAINT "document_versions_document_id_fkey" FOREIGN KEY ("document_id") REFERENCES "documents"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "document_versions" ADD CONSTRAINT "document_versions_created_by_fkey" FOREIGN KEY ("created_by") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "projects" ADD CONSTRAINT "projects_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "project_members" ADD CONSTRAINT "project_members_project_id_fkey" FOREIGN KEY ("project_id") REFERENCES "projects"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "project_members" ADD CONSTRAINT "project_members_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_project_id_fkey" FOREIGN KEY ("project_id") REFERENCES "projects"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_creator_id_fkey" FOREIGN KEY ("creator_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "task_assignees" ADD CONSTRAINT "task_assignees_task_id_fkey" FOREIGN KEY ("task_id") REFERENCES "tasks"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "task_assignees" ADD CONSTRAINT "task_assignees_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "approval_requests" ADD CONSTRAINT "approval_requests_requester_id_fkey" FOREIGN KEY ("requester_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "approval_requests" ADD CONSTRAINT "approval_requests_reviewer_id_fkey" FOREIGN KEY ("reviewer_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "approval_actions" ADD CONSTRAINT "approval_actions_request_id_fkey" FOREIGN KEY ("request_id") REFERENCES "approval_requests"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "approval_actions" ADD CONSTRAINT "approval_actions_actor_id_fkey" FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
